import axios from 'axios';

export default defineComponent({
  props: {
    apify_token: { type: 'string', secret: true, label: 'Apify API Token' }
  },
  async run({ steps, $ }) {
    // Run actor
    const run = await axios.post(
      'https://api.apify.com/v2/acts/epctex~y-combinator-scraper/runs',
      { batches: ['W25', 'S24', 'W24'], maxItems: 30 },
      { headers: { Authorization: `Bearer ${this.apify_token}` } }
    );
    const runId = run.data.data.id;

    // Wait for finish (max 60s)
    let status = 'RUNNING';
    for (let i = 0; i < 12; i++) {
      await new Promise(r => setTimeout(r, 5000));
      const s = await axios.get(`https://api.apify.com/v2/actor-runs/${runId}`, {
        headers: { Authorization: `Bearer ${this.apify_token}` }
      });
      status = s.data.data.status;
      if (status === 'SUCCEEDED') break;
    }

    // Get results
    const results = await axios.get(
      `https://api.apify.com/v2/actor-runs/${runId}/dataset/items?limit=30`,
      { headers: { Authorization: `Bearer ${this.apify_token}` } }
    );

    return (results.data || []).map(c => ({
      company: c.name || c.company_name,
      desc: c.one_liner || c.short_description || '',
      source: 'YC',
      country: c.country || 'US',
      stage: 'Pre-seed',
      capital: 'USD 500K',
      website: c.website || '',
    })).filter(c => c.company);
  }
});

import axios from 'axios';

export default defineComponent({
  props: {
    apify_token: { type: 'string', secret: true, label: 'Apify API Token' }
  },
  async run({ steps, $ }) {
    const searches = [
      'fintech startup Mexico seed',
      'startup Colombia pre-seed 2024',
      'startup Chile seed round',
      'startup Peru pre-seed',
    ];

    const allResults = [];

    for (const keyword of searches) {
      try {
        const run = await axios.post(
          'https://api.apify.com/v2/acts/curious_coder~linkedin-company-search-scraper/runs',
          { keyword, maxResults: 10 },
          { headers: { Authorization: `Bearer ${this.apify_token}` } }
        );
        const runId = run.data.data.id;

        // Wait
        for (let i = 0; i < 10; i++) {
          await new Promise(r => setTimeout(r, 5000));
          const s = await axios.get(`https://api.apify.com/v2/actor-runs/${runId}`,
            { headers: { Authorization: `Bearer ${this.apify_token}` } }
          );
          if (s.data.data.status === 'SUCCEEDED') break;
        }

        const res = await axios.get(
          `https://api.apify.com/v2/actor-runs/${runId}/dataset/items?limit=10`,
          { headers: { Authorization: `Bearer ${this.apify_token}` } }
        );

        const mapped = (res.data || []).map(c => ({
          company: c.name || c.companyName,
          desc: c.description || c.tagline || c.specialties || '',
          source: 'LinkedIn',
          country: c.headquarter?.country || 'LATAM',
          stage: 'Pre-seed',
          capital: 'USD 500K',
          website: c.websiteUrl || '',
        })).filter(c => c.company && c.desc);

        allResults.push(...mapped);
        await new Promise(r => setTimeout(r, 2000));
      } catch(e) {
        console.log(`LinkedIn search failed for: ${keyword}`, e.message);
      }
    }

    console.log(`LinkedIn: found ${allResults.length} startups`);
    return allResults;
  }
});

import axios from 'axios';

export default defineComponent({
  props: {
    apify_token: { type: 'string', secret: true, label: 'Apify API Token' }
  },
  async run({ steps, $ }) {
    const sources = [
      { url: 'https://500.co/companies', selector: '.company-card', source: '500 LATAM' },
      { url: 'https://www.startupchile.org/companies', selector: '.company-item', source: 'Startup Chile' },
      { url: 'https://endeavor.org/entrepreneurs/', selector: '.entrepreneur-card', source: 'Endeavor' },
    ];

    const allResults = [];

    for (const src of sources) {
      try {
        const run = await axios.post(
          'https://api.apify.com/v2/acts/apify~web-scraper/runs',
          {
            startUrls: [{ url: src.url }],
            pageFunction: `async function pageFunction(context) {
              const { $, request } = context;
              const companies = [];
              $('${src.selector}').each((i, el) => {
                const name = $(el).find('h2, h3, .name, .title').first().text().trim();
                const desc = $(el).find('p, .description, .bio').first().text().trim();
                if (name) companies.push({ name, desc, url: $(el).find('a').attr('href') || '' });
              });
              return companies;
            }`,
            maxPagesPerCrawl: 1,
          },
          { headers: { Authorization: `Bearer ${this.apify_token}` } }
        );
        const runId = run.data.data.id;

        for (let i = 0; i < 12; i++) {
          await new Promise(r => setTimeout(r, 5000));
          const s = await axios.get(`https://api.apify.com/v2/actor-runs/${runId}`,
            { headers: { Authorization: `Bearer ${this.apify_token}` } }
          );
          if (s.data.data.status === 'SUCCEEDED') break;
        }

        const res = await axios.get(
          `https://api.apify.com/v2/actor-runs/${runId}/dataset/items`,
          { headers: { Authorization: `Bearer ${this.apify_token}` } }
        );

        const flat = (res.data || []).flat().map(c => ({
          company: c.name,
          desc: c.desc || '',
          source: src.source,
          country: 'LATAM',
          stage: 'Seed',
          capital: 'USD 1M',
          website: c.url || '',
        })).filter(c => c.company);

        allResults.push(...flat);
      } catch(e) {
        console.log(`Failed scraping ${src.source}:`, e.message);
      }
    }

    console.log(`Aceleradoras: found ${allResults.length} startups`);
    return allResults;
  }
});

import axios from 'axios';

export default defineComponent({
  props: {
    apify_token: { type: 'string', secret: true, label: 'Apify API Token' }
  },
  async run({ steps, $ }) {
    try {
      const run = await axios.post(
        'https://api.apify.com/v2/acts/ontopo~crunchbase-companies-scraper/runs',
        {
          searchQueries: ['fintech LATAM seed', 'startup Mexico Colombia Chile pre-seed'],
          maxItems: 20,
          fundingStages: ['pre_seed', 'seed'],
          locations: ['Mexico', 'Colombia', 'Chile', 'Peru', 'Argentina'],
        },
        { headers: { Authorization: `Bearer ${this.apify_token}` } }
      );
      const runId = run.data.data.id;

      for (let i = 0; i < 12; i++) {
        await new Promise(r => setTimeout(r, 5000));
        const s = await axios.get(`https://api.apify.com/v2/actor-runs/${runId}`,
          { headers: { Authorization: `Bearer ${this.apify_token}` } }
        );
        if (s.data.data.status === 'SUCCEEDED') break;
      }

      const res = await axios.get(
        `https://api.apify.com/v2/actor-runs/${runId}/dataset/items?limit=20`,
        { headers: { Authorization: `Bearer ${this.apify_token}` } }
      );

      return (res.data || []).map(c => ({
        company: c.name || c.company_name,
        desc: c.short_description || c.description || '',
        source: 'Crunchbase',
        country: c.country_code || c.location || 'LATAM',
        stage: c.last_funding_type || 'Seed',
        capital: c.last_funding_amount ? `USD ${c.last_funding_amount}` : 'USD 1M',
        website: c.homepage_url || '',
      })).filter(c => c.company && c.desc);
    } catch(e) {
      console.log('Crunchbase scraping failed:', e.message);
      return [];
    }
  }
});

export default defineComponent({
  async run({ steps, $ }) {
    const yc   = steps.fetch_yc.$return_value || [];
    const li   = steps.fetch_linkedin.$return_value || [];
    const acc  = steps.fetch_500latam.$return_value || [];
    const cb   = steps.fetch_crunchbase.$return_value || [];

    const all = [...yc, ...li, ...acc, ...cb];

    // Deduplicate by company name
    const seen = new Set();
    const unique = all.filter(s => {
      const key = s.company?.toLowerCase().trim();
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    });

    console.log(`Sources: YC=${yc.length} LinkedIn=${li.length} Aceleradoras=${acc.length} Crunchbase=${cb.length}`);
    console.log(`Total unique startups: ${unique.length}`);
    return unique;
  }
});
